Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='forgetappends', at=datetime(2026, 10, 9, 0, 0, 0), actor='assistant', title='Forgetting appends an event and destroys a key; no pushed object is rewritten or deleted', body="Erasing words appends an event and destroys box-local material, so a store's history only grows. Every pushed object stays content-addressed, signed where it is signed, and immutable. Words already pushed in plain text stay in the data repository's history until the owner chooses to rewrite it. That rewrite is the owner's decision alone, and it drops whole paths rather than editing objects, so no surviving object is renamed.", rationale='The owner wants the data structure immutable and persistent, and rewriting objects would break signatures, references and replicas.', supersedes=()))